jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ── Audience gate ─────────────────────────────────────────────────
  var ALLOWED = {
    "andrew_nemiroff@colpal.com": 1,
    "jared_lerner@colpal.com": 1,
  };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "clause_library_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // 2026-05-21: kernel-version detection. The new bd_clauses IDB store
  // is created by the kernel's initFeatureDB requiredStores list. If an
  // admin's clause_library bundle auto-updates from CDN but their local
  // kernel hasn't been updated (Script Lab snippet, packaged add-in
  // cache, etc.), the store won't exist — calling eli.storage.getAll
  // would throw NotFoundError. Detect this via the window.STORE_BD_CLAUSES
  // export the new kernel adds; missing = old kernel. Show a friendly
  // overlay instead of crashing.
  var _kernelHasNewStore = (typeof window.STORE_BD_CLAUSES !== "undefined");
  function _showKernelUpdateOverlay() {
    var ov = document.createElement("div");
    ov.id = "_eli3_cl_kernel_update";
    ov.style.cssText =
      "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,0.55);" +
      "display:flex;align-items:center;justify-content:center;z-index:99998;" +
      "font-family:Inter,system-ui,sans-serif;";
    ov.innerHTML =
      '<div style="background:#fff;width:520px;max-width:92%;border:1px solid #cbd5e1;border-radius:0;box-shadow:0 24px 60px rgba(15,23,42,0.45);">' +
        '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);padding:14px 20px;border-bottom:3px solid #c9a227;">' +
          '<div style="font-size:10px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.22em;">Skeleton System</div>' +
          '<div style="font-family:Georgia,serif;font-size:18px;font-weight:800;color:#fff;margin-top:3px;">⚙️ Kernel update required</div>' +
        '</div>' +
        '<div style="padding:18px 22px;font-size:12.5px;line-height:1.55;color:#1e293b;">' +
          '<p style="margin:0 0 10px 0;">The <b>Clause Library</b> needs a kernel update to read/write the new <code style="font:600 11px monospace;background:#f1f5f9;padding:1px 5px;">bd_clauses</code> IndexedDB store.</p>' +
          '<p style="margin:0 0 10px 0;">Your kernel doesn\'t expose <code style="font:600 11px monospace;background:#f1f5f9;padding:1px 5px;">window.STORE_BD_CLAUSES</code>, which means it predates the 2026-05-21 IDB schema bump.</p>' +
          '<div style="background:#fefce8;border:1px solid #fde047;padding:10px 12px;margin:12px 0;font-size:11.5px;color:#713f12;">' +
            '<b>To fix:</b> deploy the latest <code style="background:#fff;padding:1px 4px;">taskpane_v3.deploy.js</code> from <code style="background:#fff;padding:1px 4px;">C:\\Users\\apndr\\Documents\\Claude Code\\</code> into your Script Lab snippet (or current kernel host), reload, then reopen this tool.' +
          '</div>' +
          '<p style="margin:0;font-size:11px;color:#64748b;">Until then, no clause data is touched — your existing templates and tools all work unchanged.</p>' +
        '</div>' +
        '<div style="padding:12px 18px;border-top:1px solid #e2e8f0;background:#f8fafc;text-align:right;">' +
          '<button id="_eli3_cl_ku_close" style="padding:7px 16px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">OK</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);
    document.getElementById("_eli3_cl_ku_close").onclick = function () {
      if (ov.parentNode) ov.parentNode.removeChild(ov);
    };
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _slug(s) {
    return String(s == null ? "" : s)
      .toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").replace(/_+/g, "_");
  }
  function _clauseId(name, variant) {
    return _slug(name || "_") + "__" + _slug(variant || "_");
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }

  // ── In-memory state (rendered to DOM on every change) ─────────────
  var _state = {
    clauses: [],
    filter: "",
    variantFilter: "",
    editId: null,            // id of clause being edited (null = no edit panel)
    creating: false,         // creating a new clause via the "+ New" button
    captureMode: false,      // creating via "Capture from Word"
    // 2026-05-21: "Used in Active Doc" filter mode. When ON we scan the
    // currently-open Word doc for #[…] / &[…] markers and limit the
    // list to clauses referenced by it. Surfaces a separate "Missing"
    // section showing #[name] references that aren't in the library yet,
    // with one-click "+ Create" buttons. The single highest-leverage
    // editing aid for skeleton authoring.
    activeDocFilter: false,
    activeDocScan: null,     // { clauseNames: [...], variants: [...], hasSkeleton: bool }
  };

  function _loadAll() {
    // Use eli.storage directly here so the caller's catch path (which
    // surfaces the friendly overlay) sees the NotFoundError, instead of
    // _safeGetAll swallowing it into [] and rendering an empty list.
    return eli.storage.getAll("bd_clauses").then(function (rows) {
      _state.clauses = (rows || []).sort(function (a, b) {
        // Group by name, then variant.
        if (a.name !== b.name) return String(a.name).localeCompare(String(b.name));
        return String(a.variant || "").localeCompare(String(b.variant || ""));
      });
      return _state.clauses;
    });
  }

  // ── Scan active doc for skeleton markers (used by activeDocFilter) ──
  function _scanActiveDocForRefs() {
    return eli.host.runRaw("clause_library:scan_active_doc", function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () {
        var text = body.text || "";
        var hashRefs = {};
        var hashRe = /#\[([^\]]+)\]/g;
        var m;
        while ((m = hashRe.exec(text)) !== null) {
          hashRefs[m[1].trim()] = true;
        }
        var variants = [];
        var variantRe = /&\[([^\]]+)\]/g;
        var mv;
        while ((mv = variantRe.exec(text)) !== null) {
          var v = mv[1].trim();
          if (variants.indexOf(v) === -1) variants.push(v);
        }
        return {
          clauseNames: Object.keys(hashRefs).sort(),
          variants: variants,
          hasSkeleton: variants.length > 0,
        };
      });
    }).catch(function (e) {
      eli.log.event("tool", "clause_library_scan_failed", { msg: e && e.message });
      return { clauseNames: [], variants: [], hasSkeleton: false };
    });
  }

  // ── Pull from Word selection ──────────────────────────────────────
  // 2026-05-21 v2: enhanced capture. Pulls BOTH text and OOXML in one
  // sync AND scans the body for the active variant at the selection
  // position (so the new-clause form can pre-fill the variant field).
  // Variant detection uses the same "context-switcher" model as the
  // build_draft resolver: walk paragraphs in doc order, track which
  // &[…] marker was most recent BEFORE the selection's first paragraph.
  function _captureSelectionWithVariant() {
    return eli.host.runRaw("clause_library:capture_with_variant", function (context) {
      var sel = context.document.getSelection();
      var ooxml = sel.getOoxml();
      sel.load("text");
      var body = context.document.body;
      body.load("text");
      var paras = body.paragraphs;
      paras.load("items/text");
      var selFirstPara = sel.paragraphs.getFirst();
      selFirstPara.load("text");
      return context.sync().then(function () {
        var text = sel.text || "";
        var oo = ooxml.value || "";
        var bodyText = body.text || "";
        var selParaText = (selFirstPara.text || "").trim();
        // Find which paragraph in the body holds the selection's first
        // paragraph. Match by text equality (sufficient for unique
        // paragraphs; falls back to first-match for repeats).
        var selParaIdx = -1;
        for (var i = 0; i < paras.items.length; i++) {
          var pt = (paras.items[i].text || "").trim();
          if (pt === selParaText) { selParaIdx = i; break; }
        }
        // Walk paragraphs 0..selParaIdx (inclusive) tracking the most
        // recent &[…] marker. Markers in the selection's own paragraph
        // ALSO count (so a selection right after a marker inherits it).
        var currentVariant = null;
        var variantMarkerRe = /&\[([^\]]+)\]/g;
        var upper = selParaIdx >= 0 ? selParaIdx : paras.items.length - 1;
        for (var j = 0; j <= upper; j++) {
          var pt2 = paras.items[j].text || "";
          variantMarkerRe.lastIndex = 0;
          var mm;
          while ((mm = variantMarkerRe.exec(pt2)) !== null) {
            currentVariant = mm[1].trim();
          }
        }
        return {
          ooxml: oo,
          text: text,
          detectedVariant: currentVariant,
          selectionParagraphIdx: selParaIdx,
          totalParagraphs: paras.items.length,
        };
      });
    });
  }

  // Back-compat alias (referenced in older capture entry points).
  function _captureSelectionOoxml() { return _captureSelectionWithVariant(); }

  // ── Render entry: full overlay (list + edit panel side-by-side) ───
  function _renderOverlay() {
    _closeOverlay();
    var overlay = document.createElement("div");
    overlay.id = "_eli3_cl_overlay";
    overlay.style.cssText =
      "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,0.55);" +
      "display:flex;align-items:center;justify-content:center;z-index:99998;" +
      "font-family:Inter,system-ui,sans-serif;";
    var card = document.createElement("div");
    card.style.cssText =
      "background:#fff;width:92%;max-width:1080px;height:88vh;" +
      "border:1px solid #cbd5e1;border-radius:0;box-shadow:0 24px 60px rgba(15,23,42,0.45);" +
      "display:flex;flex-direction:column;overflow:hidden;";
    card.innerHTML =
      // Header
      '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);padding:14px 20px;border-bottom:3px solid #c9a227;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font-size:10px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.22em;">Build Draft · Skeleton System</div>' +
          '<div style="font-family:Georgia,serif;font-size:20px;font-weight:800;color:#fff;margin-top:3px;">🧬 Skeleton Workshop</div>' +
        '</div>' +
        '<button id="_eli3_cl_close" style="background:transparent;border:none;color:#fef3c7;font-size:22px;cursor:pointer;line-height:1;">✕</button>' +
      '</div>' +
      // Body (toolbar + list + edit panel)
      '<div style="flex:1;display:flex;min-height:0;background:#f8fafc;">' +
        '<div id="_eli3_cl_left" style="flex:1;min-width:0;display:flex;flex-direction:column;border-right:1px solid #e2e8f0;">' +
          '<div id="_eli3_cl_toolbar" style="padding:10px 14px;display:flex;gap:8px;align-items:center;background:#fff;border-bottom:1px solid #e2e8f0;flex-wrap:wrap;"></div>' +
          '<div id="_eli3_cl_list" style="flex:1;overflow-y:auto;padding:8px;"></div>' +
        '</div>' +
        '<div id="_eli3_cl_right" style="width:48%;min-width:380px;display:flex;flex-direction:column;background:#fff;"></div>' +
      '</div>';
    overlay.appendChild(card);
    document.body.appendChild(overlay);
    document.getElementById("_eli3_cl_close").onclick = _closeOverlay;
    overlay.onclick = function (ev) { if (ev.target === overlay) _closeOverlay(); };
    _renderToolbar();
    _renderList();
    _renderEditPanel();
  }
  function _closeOverlay() {
    var el = document.getElementById("_eli3_cl_overlay");
    if (el && el.parentNode) el.parentNode.removeChild(el);
  }

  function _renderToolbar() {
    var bar = document.getElementById("_eli3_cl_toolbar");
    if (!bar) return;
    var variants = {};
    _state.clauses.forEach(function (c) { if (c.variant) variants[c.variant] = true; });
    var variantOpts = '<option value="">All variants</option>' +
      Object.keys(variants).sort().map(function (v) {
        return '<option value="' + _esc(v) + '"' + (v === _state.variantFilter ? " selected" : "") + '>' + _esc(v) + '</option>';
      }).join("");
    var docFilterActive = !!_state.activeDocFilter;
    var docFilterBg = docFilterActive
      ? "linear-gradient(180deg,#dbeafe,#bfdbfe)" : "linear-gradient(180deg,#f1f5f9,#e2e8f0)";
    var docFilterColor = docFilterActive ? "#1e3a8a" : "#475569";
    var docFilterBorder = docFilterActive ? "#1d4ed8" : "#cbd5e1";
    bar.innerHTML =
      '<input id="_eli3_cl_search" type="text" placeholder="🔍 Search clauses…" value="' + _esc(_state.filter) + '" ' +
        'style="flex:1;min-width:180px;padding:6px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;font-family:inherit;">' +
      '<select id="_eli3_cl_variant" style="padding:6px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;font-family:inherit;">' + variantOpts + '</select>' +
      '<button id="_eli3_cl_doc_filter" title="Toggle: show only clauses referenced by the currently-open Word document (#[…] markers in the body). Surfaces a Missing section for refs that aren\'t in the library yet." style="padding:6px 12px;font-size:11px;font-weight:800;color:' + docFilterColor + ';background:' + docFilterBg + ';border:1px solid ' + docFilterBorder + ';cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">📄 ' + (docFilterActive ? "Doc Filter ON" : "Used in Active Doc") + '</button>' +
      '<button id="_eli3_cl_new" style="padding:6px 12px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">+ New Clause</button>' +
      '<button id="_eli3_cl_pull_text" title="Capture the current Word selection as a PLAIN TEXT clause. Auto-detects which &[…] variant section the selection sits inside." style="padding:6px 12px;font-size:11px;font-weight:800;color:#155e75;background:linear-gradient(180deg,#ecfeff,#cffafe);border:1px solid #06b6d4;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">📥 Pull as Text</button>' +
      '<button id="_eli3_cl_pull_ooxml" title="Capture the current Word selection as a RICH (OOXML) clause — preserves italics, bold, tables, paragraph structure, etc. Auto-detects variant." style="padding:6px 12px;font-size:11px;font-weight:800;color:#5a330f;background:linear-gradient(180deg,#fffdf5,#fef3c7);border:1px solid #d6b347;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">📥 Pull as Rich</button>' +
      '<span id="_eli3_cl_count" style="margin-left:auto;color:#64748b;font-size:11px;"></span>';
    document.getElementById("_eli3_cl_search").oninput = function (e) {
      _state.filter = e.target.value; _renderList();
    };
    document.getElementById("_eli3_cl_variant").onchange = function (e) {
      _state.variantFilter = e.target.value; _renderList();
    };
    document.getElementById("_eli3_cl_doc_filter").onclick = function () {
      if (_state.activeDocFilter) {
        _state.activeDocFilter = false;
        _state.activeDocScan = null;
        _renderToolbar(); _renderList();
        return;
      }
      _scanActiveDocForRefs().then(function (scan) {
        _state.activeDocScan = scan;
        _state.activeDocFilter = true;
        if (!scan.clauseNames.length) {
          _toast("No #[…] clause references found in the active doc.", "warn");
        } else {
          _toast("Filtering to " + scan.clauseNames.length + " clause reference" +
            (scan.clauseNames.length === 1 ? "" : "s") + " in the active doc.", "ok");
        }
        _renderToolbar(); _renderList();
      });
    };
    document.getElementById("_eli3_cl_new").onclick = function () {
      _state.creating = true; _state.captureMode = false; _state.editId = null;
      // 2026-05-21: if doc-filter is on and prepopulate name is provided
      // (via _state._prefillCreateName from a "+ Create" click on a missing
      // clause), seed the new clause form with that name.
      _renderEditPanel();
    };
    // 2026-05-21 v2: two pull buttons — plain text or rich (OOXML).
    // Both share the same variant-detection scan; difference is which
    // format gets stored. The new clause form pre-fills:
    //   • body = captured text (plain) or OOXML (rich)
    //   • variant = auto-detected from skeleton context
    //   • format = "plain" or "ooxml" based on which button was clicked
    function _doPull(asOoxml) {
      _captureSelectionWithVariant().then(function (cap) {
        if (!cap || (!cap.ooxml && !cap.text)) {
          _toast("Nothing selected in Word — select content first, then click Pull.", "warn");
          return;
        }
        _state.creating = true; _state.editId = null;
        _state.captureMode = !!asOoxml; // captureMode = OOXML; false = plain text
        _state._capturedOoxml = cap.ooxml;
        _state._capturedText = cap.text;
        // Pre-fill variant from skeleton context (most recent &[…]
        // marker before the selection). User can override in the form.
        _state._prefillCreateVariant = cap.detectedVariant || "";
        var bodyMsg = asOoxml ? "rich (OOXML)" : "plain text";
        if (cap.detectedVariant) {
          _toast("✅ Pulled " + cap.detectedVariant + " (" + bodyMsg + "). Set the clause name + save.", "ok");
        } else {
          _toast("✅ Pulled (" + bodyMsg + "). No &[…] variant detected — set both name + variant manually.", "info");
        }
        _renderEditPanel();
      }).catch(function (e) {
        _toast("Pull failed: " + (e && e.message), "err");
      });
    }
    document.getElementById("_eli3_cl_pull_text").onclick = function () { _doPull(false); };
    document.getElementById("_eli3_cl_pull_ooxml").onclick = function () { _doPull(true); };
  }

  function _renderList() {
    var listEl = document.getElementById("_eli3_cl_list");
    var countEl = document.getElementById("_eli3_cl_count");
    if (!listEl) return;
    var f = String(_state.filter || "").toLowerCase().trim();
    var v = _state.variantFilter;
    // 2026-05-21: when activeDocFilter is on, narrow to clauses
    // referenced in the active Word doc. Also compute "missing" set —
    // doc refs that aren't in the library — and render a separate
    // section with one-click "+ Create" buttons.
    var docNames = (_state.activeDocFilter && _state.activeDocScan)
      ? _state.activeDocScan.clauseNames : null;
    var docVariants = (_state.activeDocFilter && _state.activeDocScan)
      ? _state.activeDocScan.variants : null;
    var docNameSet = {};
    if (docNames) docNames.forEach(function (n) { docNameSet[n.toLowerCase()] = true; });
    var existingNameSet = {};
    _state.clauses.forEach(function (c) {
      existingNameSet[String(c.name || "").toLowerCase()] = true;
    });
    var missingFromDoc = docNames
      ? docNames.filter(function (n) { return !existingNameSet[n.toLowerCase()]; })
      : [];
    var rows = _state.clauses.filter(function (c) {
      if (docNames && !docNameSet[String(c.name || "").toLowerCase()]) return false;
      if (v && c.variant !== v) return false;
      if (f && (String(c.name || "").toLowerCase().indexOf(f) === -1) &&
              (String(c.body || "").toLowerCase().indexOf(f) === -1)) return false;
      return true;
    });
    if (countEl) {
      if (docNames) {
        countEl.textContent = rows.length + " present · " + missingFromDoc.length + " missing · " +
          (docVariants && docVariants.length ? "variants: " + docVariants.join(", ") : "no &[] variants");
      } else {
        countEl.textContent = rows.length + " of " + _state.clauses.length;
      }
    }
    // Header for active-doc filter
    var docHeader = "";
    if (docNames) {
      docHeader =
        '<div style="background:linear-gradient(180deg,#dbeafe,#bfdbfe);border:1px solid #60a5fa;padding:8px 12px;margin-bottom:8px;font-size:11px;color:#1e3a8a;">' +
          '<b>📄 Active Doc Filter:</b> showing clauses referenced by the open Word document. ' +
          (docVariants && docVariants.length
            ? 'Variants in skeleton: <code style="background:#fff;padding:1px 5px;font-family:monospace;border:1px solid #60a5fa;">' +
              docVariants.map(_esc).join(", ") + '</code>'
            : '<i>No &amp;[…] variant declarations found — this isn\'t a skeleton template.</i>') +
        '</div>';
    }
    if (!rows.length && !missingFromDoc.length) {
      listEl.innerHTML = docHeader +
        '<div style="padding:32px;text-align:center;color:#64748b;font-size:12px;">' +
          (_state.clauses.length === 0
            ? '<div style="font-size:32px;margin-bottom:8px;">📚</div><b>No clauses yet.</b><br>Click <strong>+ New Clause</strong> to start, or <strong>Capture from Word</strong> to grab a formatted block.'
            : (docNames ? '<b>No #[…] references in active doc.</b><br>Either nothing references the library here, or the doc has no skeleton markers.'
                        : '<b>No matches.</b><br>Try a different search.')) +
        '</div>';
      return;
    }
    var missingHtml = "";
    if (missingFromDoc.length) {
      missingHtml =
        '<div style="margin-top:18px;background:#fef2f2;border:1px solid #fca5a5;padding:10px 12px;">' +
          '<div style="font:800 10px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#991b1b;margin-bottom:8px;">' +
            '⚠️ Missing from library (' + missingFromDoc.length + ')' +
          '</div>' +
          '<div style="font-size:11px;color:#7f1d1d;margin-bottom:8px;">' +
            'These #[…] markers in the active doc don\'t have a matching clause in the library. Click + Create to add one.' +
          '</div>' +
          missingFromDoc.map(function (n) {
            return '<div class="_eli3_cl_missing_row" data-cl-name="' + _esc(n) + '" style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 8px;background:#fff;border:1px solid #fecaca;margin-bottom:4px;">' +
              '<code style="font:600 11px/1.2 monospace;color:#7f1d1d;background:transparent;">#[' + _esc(n) + ']</code>' +
              '<button class="_eli3_cl_missing_create" data-cl-name="' + _esc(n) + '" style="padding:4px 10px;font-size:10px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">+ Create</button>' +
            '</div>';
          }).join("") +
        '</div>';
    }
    if (!rows.length) {
      listEl.innerHTML = docHeader +
        '<div style="padding:18px 12px;text-align:center;color:#64748b;font-size:12px;font-style:italic;">' +
          (docNames ? 'No library clauses match the active doc\'s references.' : 'No matches.') +
        '</div>' + missingHtml;
      _wireMissingButtons();
      return;
    }
    listEl.innerHTML = docHeader + rows.map(function (c) {
      var preview = String(c.body || "").substring(0, 120).replace(/\s+/g, " ").trim();
      if (preview.length > 110) preview = preview.substring(0, 110) + "…";
      var isActive = (_state.editId === c.id);
      var formBadge = c.format === "ooxml"
        ? '<span style="font-size:9px;font-weight:800;color:#5a330f;background:#fef3c7;border:1px solid #d6b347;padding:1px 5px;letter-spacing:0.1em;text-transform:uppercase;">OOXML</span>'
        : '<span style="font-size:9px;font-weight:800;color:#155e75;background:#cffafe;border:1px solid #67e8f9;padding:1px 5px;letter-spacing:0.1em;text-transform:uppercase;">Plain</span>';
      return '<div class="_eli3_cl_row" data-cl-id="' + _esc(c.id) + '" style="background:' + (isActive ? "#fef9e0" : "#fff") + ';border:1px solid ' + (isActive ? "#c9a227" : "#e2e8f0") + ';border-left:3px solid ' + (isActive ? "#c9a227" : "#cbd5e1") + ';padding:8px 12px;margin-bottom:6px;cursor:pointer;">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">' +
          '<div style="min-width:0;flex:1;">' +
            '<div style="font:700 12px/1.2 Inter,sans-serif;color:#0f172a;">' + _esc(c.name) + '</div>' +
            '<div style="font:500 10px/1.3 Inter,sans-serif;color:#64748b;margin-top:2px;">' + _esc(c.variant || "(no variant)") + '</div>' +
            '<div style="font:400 11px/1.4 Georgia,serif;color:#475569;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(preview) + '</div>' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:3px;align-items:flex-end;flex-shrink:0;">' +
            formBadge +
            '<span style="font:500 9px/1 Inter,sans-serif;color:#94a3b8;">v' + (c.version || 1) + '</span>' +
          '</div>' +
        '</div>' +
      '</div>';
    }).join("");
    // Append missing-from-doc section (only meaningful when doc filter is on).
    if (missingHtml) listEl.insertAdjacentHTML("beforeend", missingHtml);
    listEl.querySelectorAll("._eli3_cl_row").forEach(function (row) {
      row.onclick = function () {
        var id = row.getAttribute("data-cl-id");
        _state.editId = id; _state.creating = false; _state.captureMode = false;
        _renderList(); _renderEditPanel();
      };
    });
    _wireMissingButtons();
  }

  // Wire the "+ Create" buttons in the Missing section — opens the
  // new-clause form pre-populated with the clause name + active doc's
  // first variant (best guess for what variant the user wants).
  function _wireMissingButtons() {
    var listEl = document.getElementById("_eli3_cl_list");
    if (!listEl) return;
    listEl.querySelectorAll("._eli3_cl_missing_create").forEach(function (btn) {
      btn.onclick = function (ev) {
        ev.stopPropagation();
        var name = btn.getAttribute("data-cl-name") || "";
        _state.creating = true;
        _state.captureMode = false;
        _state.editId = null;
        _state._prefillCreateName = name;
        _state._prefillCreateVariant = (_state.activeDocScan && _state.activeDocScan.variants &&
          _state.activeDocScan.variants[0]) || "";
        _renderEditPanel();
      };
    });
  }

  function _renderEditPanel() {
    var rightEl = document.getElementById("_eli3_cl_right");
    if (!rightEl) return;
    var c;
    if (_state.editId) {
      c = _state.clauses.find(function (x) { return x.id === _state.editId; });
      if (!c) { _state.editId = null; _renderEditPanel(); return; }
    } else if (_state.creating) {
      // 2026-05-21 fix: when pulling as PLAIN text (captureMode=false
      // but _state._capturedText is set), pre-fill the body with the
      // captured text. The previous code only pre-filled when in
      // captureMode (OOXML), leaving plain-text pulls with an empty
      // body field.
      var prefillBody;
      if (_state.captureMode) {
        prefillBody = _state._capturedOoxml || "";
      } else if (_state._capturedText) {
        prefillBody = _state._capturedText;
      } else {
        prefillBody = "";
      }
      c = {
        id: "",
        name: _state._prefillCreateName || "",
        variant: _state._prefillCreateVariant || "",
        body: prefillBody,
        format: _state.captureMode ? "ooxml" : "plain",
        version: 1, modifiedAt: new Date().toISOString(),
      };
      // One-shot prefill — consume so it doesn't reappear on next "+ New".
      delete _state._prefillCreateName;
      delete _state._prefillCreateVariant;
    } else {
      rightEl.innerHTML =
        '<div style="padding:48px 32px;text-align:center;color:#94a3b8;font-size:12px;">' +
          '<div style="font-size:36px;margin-bottom:10px;">📋</div>' +
          '<b>Select a clause</b><br>or click <strong>+ New Clause</strong> to create one.' +
        '</div>';
      return;
    }
    var isCreating = _state.creating;
    var isOoxml = c.format === "ooxml";
    var captureNote = (_state.captureMode && _state.creating)
      ? '<div style="background:#fefce8;border:1px solid #fde047;padding:8px 12px;font-size:11px;color:#713f12;margin-bottom:10px;">' +
          '<b>📥 Captured from Word selection.</b><br>' +
          'Preview text (~' + (String(_state._capturedText || "").length) + ' chars). The OOXML body is stored for full-fidelity insertion at resolve time.' +
        '</div>'
      : "";
    var bodyEditor;
    if (isOoxml && !isCreating) {
      // Editing an existing OOXML clause — no inline edit, recapture only.
      bodyEditor =
        '<div style="background:#f8fafc;border:1px dashed #cbd5e1;padding:14px;text-align:center;color:#64748b;font-size:11px;">' +
          '<b>OOXML clause (rich formatting).</b><br>' +
          'To edit, click <strong>📥 Recapture from Word</strong> below — opens the current OOXML in a scratch flow, you edit in Word and recapture.' +
        '</div>' +
        '<div style="font:500 11px/1.4 Georgia,serif;color:#475569;background:#fff;border:1px solid #e2e8f0;padding:10px 12px;margin-top:6px;max-height:200px;overflow-y:auto;white-space:pre-wrap;">' +
        _esc(String(c.body || "").substring(0, 800)) + (String(c.body || "").length > 800 ? "…" : "") +
        '</div>';
    } else {
      var bodyVal = isCreating && _state.captureMode ? (_state._capturedText || "") : (c.body || "");
      bodyEditor =
        captureNote +
        '<textarea id="_eli3_cl_body" placeholder="Clause body text (plain). Use \\n\\n for paragraph breaks." style="width:100%;height:280px;padding:10px 12px;font:500 12px/1.55 Georgia,serif;color:#0f172a;background:#fff;border:1px solid #cbd5e1;resize:vertical;box-sizing:border-box;">' +
        _esc(bodyVal) + '</textarea>';
    }
    rightEl.innerHTML =
      '<div style="padding:14px 16px;border-bottom:1px solid #e2e8f0;background:#f8fafc;">' +
        '<div style="font-size:9.5px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.18em;">' +
          (isCreating ? (_state.captureMode ? "New clause · captured from Word" : "New clause") : "Edit clause") +
        '</div>' +
      '</div>' +
      '<div style="flex:1;overflow-y:auto;padding:14px 16px;">' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Clause Name</label>' +
          '<input id="_eli3_cl_name" type="text" value="' + _esc(c.name) + '" placeholder="e.g. Recitals 1, or Limitation of Liability" style="width:100%;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;box-sizing:border-box;">' +
          '<div style="font-size:10px;color:#94a3b8;margin-top:3px;">Referenced from skeleton as <code style="font-family:monospace;background:#f1f5f9;padding:1px 4px;">#[' + (_esc(c.name) || "Clause Name") + ']</code></div>' +
        '</div>' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Variant</label>' +
          '<input id="_eli3_cl_variant_in" type="text" value="' + _esc(c.variant) + '" placeholder="e.g. Mutual NDA, Services Agreement" style="width:100%;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;box-sizing:border-box;">' +
          '<div style="font-size:10px;color:#94a3b8;margin-top:3px;">Matches the skeleton\'s <code style="font-family:monospace;background:#f1f5f9;padding:1px 4px;">&amp;[' + (_esc(c.variant) || "Variant") + ']</code> declaration (case-insensitive).</div>' +
        '</div>' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Body (<span id="_eli3_cl_fmt_label">' + (isOoxml ? "OOXML" : "plain text") + '</span>)</label>' +
          bodyEditor +
        '</div>' +
      '</div>' +
      '<div style="padding:12px 16px;border-top:1px solid #e2e8f0;background:#f8fafc;display:flex;gap:8px;justify-content:flex-end;">' +
        (isCreating
          ? ''
          : '<button id="_eli3_cl_delete" style="margin-right:auto;padding:7px 14px;font-size:11px;font-weight:800;color:#991b1b;background:#fff;border:1px solid #fca5a5;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">🗑️ Delete</button>') +
        (isOoxml && !isCreating
          ? '<button id="_eli3_cl_recapture" style="padding:7px 14px;font-size:11px;font-weight:800;color:#5a330f;background:linear-gradient(180deg,#fffdf5,#fef3c7);border:1px solid #d6b347;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">📥 Recapture</button>'
          : '') +
        '<button id="_eli3_cl_cancel" style="padding:7px 14px;font-size:11px;font-weight:800;color:#475569;background:#fff;border:1px solid #cbd5e1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">Cancel</button>' +
        '<button id="_eli3_cl_save" style="padding:7px 14px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">💾 Save</button>' +
      '</div>';
    document.getElementById("_eli3_cl_cancel").onclick = function () {
      _state.editId = null; _state.creating = false; _state.captureMode = false;
      delete _state._capturedOoxml; delete _state._capturedText;
      _renderList(); _renderEditPanel();
    };
    document.getElementById("_eli3_cl_save").onclick = function () {
      var name = document.getElementById("_eli3_cl_name").value.trim();
      var variant = document.getElementById("_eli3_cl_variant_in").value.trim();
      var bodyEl = document.getElementById("_eli3_cl_body");
      var body;
      if (isOoxml && !isCreating) {
        body = c.body; // unchanged (recapture flow only changes body)
      } else if (_state.captureMode && _state.creating) {
        body = _state._capturedOoxml || "";
      } else {
        body = (bodyEl && bodyEl.value) || "";
      }
      if (!name) { _toast("Name required.", "warn"); return; }
      var format = isOoxml ? "ooxml" : "plain";
      var newId = isCreating ? _clauseId(name, variant) : c.id;
      var row = {
        id: newId,
        name: name,
        variant: variant,
        body: body,
        format: format,
        version: isCreating ? 1 : (Number(c.version || 0) + 1),
        modifiedAt: new Date().toISOString(),
        modifiedBy: userEmail || null,
      };
      eli.storage.put("bd_clauses", row).then(function () {
        return _loadAll();
      }).then(function () {
        _state.editId = row.id; _state.creating = false; _state.captureMode = false;
        delete _state._capturedOoxml; delete _state._capturedText;
        _renderList(); _renderEditPanel();
        _toast(isCreating ? "✅ Clause created" : "✅ Clause saved (v" + row.version + ")", "ok");
      }).catch(function (e) {
        _toast("Save failed: " + (e && e.message), "err");
      });
    };
    var delBtn = document.getElementById("_eli3_cl_delete");
    if (delBtn) delBtn.onclick = function () {
      eli.events.safeAsync(eli.ui.confirm({
        title: "Delete clause?",
        message: "Delete '" + (c.name || "this clause") + "' (" + (c.variant || "no variant") + ")?",
      }), "clause_library.delete_confirm").then(function (ok) {
        if (!ok) return;
        return eli.storage.delete("bd_clauses", c.id).then(function () {
          return _loadAll();
        }).then(function () {
          _state.editId = null;
          _renderList(); _renderEditPanel();
          _toast("🗑️ Deleted", "ok");
        });
      });
    };
    var recapBtn = document.getElementById("_eli3_cl_recapture");
    if (recapBtn) recapBtn.onclick = function () {
      _captureSelectionOoxml().then(function (cap) {
        if (!cap || !cap.ooxml) {
          _toast("Nothing selected in Word — select replacement content first.", "warn");
          return;
        }
        c.body = cap.ooxml;
        c.version = Number(c.version || 0) + 1;
        c.modifiedAt = new Date().toISOString();
        return eli.storage.put("bd_clauses", c).then(function () {
          return _loadAll();
        }).then(function () {
          _renderList(); _renderEditPanel();
          _toast("✅ Recaptured (v" + c.version + ")", "ok");
        });
      });
    };
  }

  // ── Tile / dispatch entry ─────────────────────────────────────────
  function _open() {
    // Defensive: if the kernel doesn't know about bd_clauses, the store
    // doesn't exist in IDB and getAll will throw. Show a friendly
    // update-kernel overlay instead of cascading the error.
    if (!_kernelHasNewStore) {
      eli.log.event("tool", "clause_library_kernel_too_old", { email: userEmail });
      _showKernelUpdateOverlay();
      return;
    }
    _loadAll().then(function () { _renderOverlay(); }).catch(function (e) {
      // Belt-and-suspenders: even when window.STORE_BD_CLAUSES is set
      // (kernel updated) but a NotFoundError still occurs (e.g., stale
      // IDB version cache from before the kernel update), surface the
      // same friendly message instead of a raw IDB error.
      var msg = String(e && e.message || "");
      if (/not\s*found/i.test(msg) || /one of the specified object stores/i.test(msg)) {
        eli.log.event("tool", "clause_library_idb_store_missing", { msg: msg });
        _showKernelUpdateOverlay();
        return;
      }
      eli.log.event("tool", "clause_library_open_failed", { msg: msg });
      _toast("Failed to load clauses: " + msg, "err");
    });
  }

  // Safe IDB helpers — return empty/null on missing store instead of
  // throwing. Protects callers (e.g. build_draft's resolver) when the
  // user runs an admin tool bundle against an older kernel.
  function _safeGetAll() {
    if (!_kernelHasNewStore) return Promise.resolve([]);
    return eli.storage.getAll("bd_clauses").catch(function (e) {
      var msg = String(e && e.message || "");
      if (/not\s*found/i.test(msg) || /one of the specified object stores/i.test(msg)) {
        return [];
      }
      throw e;
    });
  }

  eli.register({
    tile: { app_clause_library: _open },
    clauses: {
      open: _open,
      getAll: _safeGetAll,
      lookup: function (name, variant) {
        // Lookup with variant fallback: exact (name+variant), then
        // name+"" (no variant), then null.
        // 2026-05-21: normalize both name + variant aggressively before
        // comparing — case-insensitive, whitespace-collapsed, and all
        // dash variants normalized to `-` (Word autocorrects `-` to en-
        // dash `–` or em-dash `—` inside brackets, breaking lookup
        // against clauses stored with regular hyphens).
        function _norm(s) {
          return String(s || "")
            .toLowerCase()
            .replace(/[‐-―−]/g, "-") // unicode dashes → hyphen
            .replace(/\s+/g, " ")
            .trim();
        }
        return _safeGetAll().then(function (rows) {
          rows = rows || [];
          var nl = _norm(name);
          var vl = _norm(variant);
          var exact = rows.find(function (r) {
            return _norm(r.name) === nl && _norm(r.variant) === vl;
          });
          if (exact) return exact;
          // Fallback: clause with same name and ANY variant (last-wins).
          var any = rows.filter(function (r) { return _norm(r.name) === nl; });
          if (any.length === 1) return any[0]; // single-variant clause works for any variant
          return null;
        });
      },
    },
  });
  eli.log.event("tool", "clause_library_init", { email: userEmail });
}
